content.text:
{
  "primary_meaning": "A temporary, incomplete, or typological foreshadowing of a greater spiritual reality (especially Christ, the gospel, or heavenly things)",
  "primary_basis": [
    "Colossians 2:16-17",
    "Hebrews 8:5",
    "Hebrews 10:1"
  ],
  "alternatives": [
    {
      "meaning": "Divine protection, covering, or refuge under God's care",
      "basis": [
        "Psalm 17:8",
        "Psalm 36:7",
        "Psalm 57:1",
        "Psalm 91:1",
        "Isaiah 25:4"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Death, deep darkness, or the realm of mortality and threat",
      "basis": [
        "Psalm 23:4",
        "Job 3:5",
        "Isaiah 9:2",
        "Luke 1:79",
        "Matthew 4:16"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The fleeting, insubstantial, or transient nature of human life",
      "basis": [
        "Job 8:9",
        "Job 14:2",
        "Psalm 102:11",
        "Psalm 144:4",
        "Ecclesiastes 6:12"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Absence of variation, turning, or imperfection (applied to God)",
      "basis": [
        "James 1:17"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "high",
  "notes": "Biblical usage of 'shadow' is strongly context-dependent; the typological sense is especially prominent in Christian theological interpretation of Old Testament institutions, while protective and death-related senses dominate in the Psalms and prophetic literature. No single meaning monopolizes Christian teaching."
}
